INSERT INTO diag_baru VALUES
  (1, 'Ada dua kegiatan di laboratorium komputer kampus. Kegiatan pertama mencari tahu mengapa jumlah komputer yang rusak naik dalam satu semester. Kegiatan kedua merancang jadwal perawatan berkala beserta lembar cek untuk teknisi. Pernyataan mana yang paling tepat menggambarkan kedua kegiatan itu?', '["Kegiatan pertama pengembangan karena berangkat dari masalah nyata, kegiatan kedua penelitian terapan karena memakai data dari teknisi", "Kegiatan pertama penelitian terapan karena menjawab pertanyaan praktis, kegiatan kedua pengembangan karena menghasilkan alat", "Keduanya penelitian terapan, karena sama-sama berlangsung di tempat kerja dan berkaitan dengan masalah yang sama di laboratorium itu", "Keduanya pengembangan, karena sama-sama bertujuan mengurangi kerusakan komputer dan hasilnya akan dipakai oleh pihak laboratorium"]'::JSONB, 1, '[C2] Penelitian terapan menjawab pertanyaan praktis dengan data lapangan, sedangkan pengembangan menghasilkan sesuatu yang baru dan bisa langsung dipakai. Kesamaan tempat atau tujuan tidak mengubah jenis kegiatannya.', 1),
  (1, 'Sebuah laporan penelitian di perpustakaan kampus memuat temuan: "Mahasiswa tingkat awal enggan bertanya kepada pustakawan karena takut pertanyaannya dianggap remeh, dan sebagian merasa meja referensi terlihat terlalu resmi." Temuan seperti itu paling mungkin dihasilkan oleh penelitian dengan paradigma apa?', '["Kuantitatif, karena temuannya menyebut kata sebagian sehingga berasal dari perhitungan persentase", "R&D, karena temuannya akan dipakai untuk merancang ulang meja referensi agar terlihat lebih ramah", "Kuantitatif, karena temuannya menunjukkan hubungan antara rasa takut dan jumlah pertanyaan yang diajukan", "Kualitatif, karena temuannya berupa penjelasan tentang perasaan dan alasan yang digali dari narasumber"]'::JSONB, 3, '[C2] Temuan berupa alasan dan perasaan orang adalah hasil khas pendekatan kualitatif yang menggali makna lewat wawancara atau observasi. Kata "sebagian" tidak menjadikannya kuantitatif karena tidak ada ukuran atau angka yang dilaporkan.', 2),
  (1, 'Seorang mahasiswa yang merancang aplikasi pemesanan ruang diskusi perpustakaan menyiapkan lembar validasi, sedangkan temannya yang meneliti kepuasan pengunjung cukup menyiapkan angket berskala. Mengapa lembar validasi lazim dipakai pada R&D tetapi jarang pada penelitian kuantitatif atau kualitatif?', '["Karena R&D menghasilkan produk yang perlu dinilai kelayakannya oleh ahli sebelum dicobakan kepada pengguna", "Karena R&D tidak memakai angket, sehingga lembar validasi menggantikan angket sebagai alat pengumpul data utama", "Karena lembar validasi menghasilkan angka, sedangkan penelitian kuantitatif tidak memerlukan penilaian dari ahli", "Karena lembar validasi dipakai untuk menguji hipotesis tentang hubungan variabel pada produk yang dirancang"]'::JSONB, 0, '[C2] Luaran R&D berupa produk, sehingga diperlukan alat untuk menilai kelayakannya sebelum diuji coba. R&D tetap memakai angket, seperti tercantum pada Tabel 1.3, jadi lembar validasi bukan pengganti angket.', 3),
  (1, 'Seorang mahasiswa magang di perpustakaan sekolah menulis empat calon pertanyaan untuk proyeknya. Pertanyaan mana yang paling tepat dijawab dengan paradigma R&D?', '["Berapa jumlah rata-rata buku yang dipinjam siswa kelas X setiap minggu selama semester ganjil?", "Mengapa siswa kelas XII jarang meminjam buku fiksi meskipun koleksinya baru saja ditambah?", "Bagaimana rancangan panduan menyampul buku yang layak dipakai petugas baru di sekolah itu?", "Seberapa besar hubungan antara frekuensi kunjungan siswa dan nilai rapor mata pelajaran bahasa?"]'::JSONB, 2, '[C3] Pertanyaan yang hasil akhirnya berupa benda atau prosedur yang akan dipakai orang lain (panduan) mengarah ke R&D. Pertanyaan "berapa" dan "seberapa besar" mengarah ke kuantitatif, sedangkan "mengapa" mengarah ke kualitatif.', 4),
  (1, 'Mahasiswa akan mengamati alur pengembalian buku di perpustakaan fakultas selama 30 menit untuk tugas kuliahnya. Ia belum menghubungi siapa pun di perpustakaan itu. Langkah pertama mana yang paling tepat?', '["Menyampaikan tujuan tugas, lama pengamatan, dan hal yang akan dicatat kepada kepala perpustakaan", "Langsung mengamati dari kursi pengunjung agar petugas bersikap wajar dan tidak merasa sedang dinilai", "Memotret meja pengembalian lebih dulu sebagai bukti, lalu meminta izin setelah pengamatan selesai", "Meminta petugas mengisi angket tentang alur pengembalian sebelum pengamatan dimulai di meja layanan"]'::JSONB, 0, '[C3] Kewajiban pertama adalah izin: tujuan, lama pengamatan, dan hal yang dicatat disampaikan kepada kepala unit sebelum mulai. Mengamati diam-diam memang membuat petugas bersikap wajar, tetapi melewati izin dan kesediaan mereka.', 5),
  (1, 'Mahasiswa ingin menyusun proyek di unit layanan akademik kampus. Urutan langkah awal mana yang paling sesuai dengan cara kerja yang dimulai dari masalah, bukan dari metode?', '["Memilih paradigma yang paling dikuasai, merumuskan pertanyaan, lalu mencari unit layanan yang cocok", "Menentukan produk aplikasi, mengamati unit layanan, lalu merumuskan pertanyaan yang mendukung produk", "Menyusun angket berskala, menyebarkannya di unit layanan, lalu merumuskan pertanyaan dari hasilnya", "Mengamati fenomena di unit layanan, merumuskan pertanyaan penelitian, lalu memilih paradigma dan metode"]'::JSONB, 3, '[C3] Urutan problem driven research adalah mengamati fenomena, merumuskan pertanyaan, baru memilih paradigma dan metode. Menentukan produk lebih dulu tampak praktis, tetapi itu melompat ke solusi sebelum masalahnya dipahami.', 6),
  (1, 'Dosen mengizinkan mahasiswa memakai alat AI generatif untuk merapikan kalimat berkas AM-1. Seorang mahasiswa memakai ChatGPT untuk memperbaiki tata bahasa paragraf masalah yang ia tulis dari pengamatannya di perpustakaan kampus. Apa yang sebaiknya ia lakukan?', '["Tidak menyebut apa pun, karena isi paragraf tetap berasal dari pengamatannya sendiri", "Menulis di akhir berkas alat yang dipakai dan bagian yang dirapikan dengan alat itu", "Mencantumkan ChatGPT di daftar rujukan seperti artikel jurnal yang dikutip dalam teks", "Meminta ChatGPT sekalian menambahkan data antrean agar paragraf masalahnya lebih lengkap"]'::JSONB, 1, '[C3] Bab ini meminta mahasiswa menulis di akhir berkas alat apa yang dipakai dan untuk bagian mana bila dosen mengizinkan. Meminta AI menambahkan data lapangan termasuk fabrikasi, dan menyembunyikan pemakaiannya tidak terbuka.', 7),
  (1, 'Catatan pengamatan di perpustakaan pascasarjana memuat tiga kalimat (angka rekaan). (1) Layanan perpustakaan ini kurang memuaskan. (2) Selama dua jam pengamatan, 14 dari 30 pengunjung menunggu lebih dari 10 menit di meja pengembalian. (3) Petugasnya tampak kurang peduli pada pengunjung. Kalimat mana yang paling layak dipakai di kolom masalah AM-1, dan mengapa?', '["Kalimat (1), karena merangkum keadaan layanan secara umum dalam satu kalimat ringkas", "Kalimat (3), karena menunjukkan penyebab utama antrean yang dialami para pengunjung itu", "Kalimat (2), karena menggambarkan kondisi yang dapat diamati dan diperiksa ulang orang lain", "Kalimat (1) dan (3), karena keduanya menggambarkan pengalaman pengunjung secara jujur"]'::JSONB, 2, '[C4] Kolom masalah AM-1 meminta kondisi yang bisa diamati, bukan opini. Kalimat (3) tampak menjelaskan sebab, tetapi "kurang peduli" adalah kesan pengamat yang belum didukung catatan perilaku.', 8),
  (1, 'Rencana proyek seorang mahasiswa di perpustakaan umum kota (rekaan): "Saya akan menyebar angket kepuasan, mewawancarai pustakawan, dan membuat aplikasi katalog. Ketiganya sama penting dan dikerjakan bersamaan." Apa kelemahan utama rencana itu?', '["Angket dan wawancara tidak dapat dipakai bersama karena berasal dari dua paradigma yang berbeda", "Aplikasi katalog sebaiknya diganti produk nonteknologi karena lebih mudah diuji dalam satu semester", "Wawancara dengan pustakawan kurang ilmiah dibanding angket karena tidak menghasilkan data angka", "Paradigma utama tidak jelas, sehingga tidak tampak kegiatan mana yang menopang kegiatan lain"]'::JSONB, 3, '[C4] Mencampur ketiga paradigma tanpa paradigma utama membuat proposal tidak fokus. Angket dan wawancara justru boleh dipakai bersama, misalnya pada tahap awal R&D untuk memahami masalah.', 9),
  (1, 'Pada minggu pertama, seorang mahasiswa langsung menulis kode aplikasi peminjaman ruang diskusi perpustakaan. Ia beralasan: "Proyek saya R&D, jadi intinya membuat produk. Data masalah bisa dicari nanti untuk melengkapi laporan." Apa kekeliruan utama dalam alasan itu?', '["R&D yang baik diawali pengumpulan data masalah, agar produk dirancang untuk menjawab masalah yang dipahami", "R&D seharusnya menghasilkan model teoretis, sehingga aplikasi peminjaman ruang tidak termasuk luaran yang sah", "Pembuatan aplikasi memerlukan izin kepala perpustakaan, sehingga kode belum dapat ditulis pada minggu pertama", "Data masalah cukup diambil dari penelitian lain, sehingga mahasiswa tidak perlu mengamati perpustakaan sendiri"]'::JSONB, 0, '[C4] Bab ini mencatat kesalahan umum menyamakan R&D dengan membuat produk secara langsung tanpa analisis kebutuhan. Izin memang diperlukan untuk mengamati, tetapi izin bukan kekeliruan utama dalam alasan itu.', 10),
  (2, 'Seorang mahasiswa ingin mengetahui kendala di layanan referensi perpustakaan kampus. Ia sudah mewawancarai dua pustakawan, tetapi dosen tetap memintanya mengamati layanan itu secara langsung. Alasan yang paling tepat untuk permintaan dosen itu adalah ...', '["Wawancara dengan pustakawan cukup untuk keperluan kuliah, observasi untuk kebutuhan skripsi", "Apa yang diceritakan narasumber dapat berbeda dari apa yang benar-benar ia kerjakan", "Observasi memberi data angka, sedangkan wawancara tidak dapat dipakai sebagai bukti masalah", "Pustakawan biasanya menolak diwawancarai lebih dari sekali dalam satu semester perkuliahan"]'::JSONB, 1, '[C2] Narasumber hanya menceritakan apa yang ia sadari dan bersedia ia sampaikan, sehingga observasi menangkap hal yang tidak muncul dalam wawancara. Kutipan wawancara tetap sah sebagai bukti, jadi anggapan bahwa wawancara tidak dapat dipakai keliru.', 11),
  (2, 'Pengunjung ruang baca lantai dua sebuah perpustakaan kampus turun tajam. Kepala perpustakaan langsung ingin menambah kursi baru. Seorang mahasiswa menyarankan agar penyebabnya diurai lebih dulu dengan diagram tulang ikan. Manfaat utama saran mahasiswa itu adalah ...', '["Laporan kepada kepala perpustakaan terlihat lebih ilmiah karena memuat sebuah diagram", "Solusi yang dirancang menyasar penyebab, tidak sekadar menambal gejala di permukaan", "Rencana menambah kursi baru dapat dibatalkan tanpa perlu meminta pendapat pemustaka", "Pihak yang paling sering mengeluh dapat langsung ditunjuk sebagai penyebab utama masalah"]'::JSONB, 1, '[C2] Mengurai penyebab mencegah kesimpulan terburu-buru, misalnya menambah kursi padahal pengunjung pergi karena alasan lain. Diagram bukan hiasan laporan; nilainya ada pada penyebab yang dipetakan.', 12),
  (2, 'Dalam proposal, seorang mahasiswa menulis bahwa layanan unggah mandiri repositori kampus bermasalah. Penguji bertanya, "Apa buktinya masalah ini benar-benar terjadi?" Bagian proposal yang seharusnya menjawab pertanyaan itu berisi ...', '["Rencana fitur repositori baru yang akan dibuat beserta perkiraan biaya pengembangannya", "Data awal, kutipan wawancara, atau dokumen dari lokasi yang menunjukkan masalahnya nyata", "Definisi repositori institusi dari beberapa buku teks ilmu perpustakaan dan informasi", "Pendapat pribadi mahasiswa tentang pengalaman mengunggah tugas ke repositori kampus"]'::JSONB, 1, '[C2] Studi pendahuluan adalah rangkuman awal yang membuktikan masalah benar terjadi, berupa data, kutipan, atau dokumentasi lapangan. Pengalaman pribadi mahasiswa tampak dekat dengan bukti, tetapi masih persepsi satu orang.', 13),
  (2, 'Seorang mahasiswa menduga ruang baca lantai tiga di perpustakaan kampusnya makin sepi sejak dua semester terakhir. Ia ingin memperkuat dugaan itu dengan dokumen yang sudah ada di perpustakaan. Dokumen mana yang paling tepat ditelaah?', '["Brosur pengenalan perpustakaan yang dibagikan kepada mahasiswa baru", "Dokumen visi dan misi perpustakaan yang tercantum di laman web kampus", "Daftar judul buku baru yang dibeli perpustakaan pada semester ini", "Rekap jumlah pengunjung per lantai setiap bulan selama dua tahun terakhir"]'::JSONB, 3, '[C3] Rekap pengunjung per lantai memuat angka yang dapat menunjukkan penurunan dari waktu ke waktu. Daftar buku baru memang dokumen resmi, tetapi tidak berkaitan dengan jumlah pengunjung ruang baca.', 14),
  (2, 'Mahasiswa PKL di perpustakaan sekolah sudah mengamati layanan sirkulasi dan mewawancarai pustakawan. Kebutuhan pengguna sudah ia rumuskan, dan ia mulai menimbang produk yang akan dibuat. Kepala perpustakaan adalah pemberi izin, tetapi belum pernah diajak bicara tentang proyek ini. Langkah yang paling tepat ia lakukan sekarang adalah ...', '["Menanyakan kepada kepala perpustakaan apakah produk nanti boleh diujicobakan di perpustakaan itu", "Menyelesaikan rancangan produk lebih dulu, lalu meminta izin sesudah produk siap diujicobakan di sana", "Menambah wawancara dengan siswa agar daftar kebutuhan pengguna menjadi lebih panjang dan rinci", "Meminta kepala perpustakaan mengisi angket kepuasan layanan sirkulasi sebagai data tambahan"]'::JSONB, 0, '[C3] Stefaniak (2026) mencatat asesmen kebutuhan sering terhambat oleh kurangnya dukungan pemangku kepentingan, jadi pemberi izin ditanya sejak awal apakah produk boleh diujicobakan di unitnya. Meminta izin sesudah produk jadi berisiko produk tidak boleh diuji; menambah wawancara atau angket kepuasan tidak menjawab soal izin.', 15),
  (2, 'Mahasiswa akan mengamati layanan peminjaman di perpustakaan fakultas selama 40 menit pada hari Senin. Ia sudah menyiapkan lembar catatan berkolom deskripsi dan tafsiran. Rencana pencatatan mana yang paling tepat?', '["Mengamati tanpa menulis agar petugas tidak terganggu, lalu menyusun catatan dari ingatan pada akhir pekan", "Memotret suasana layanan, lalu menulis deskripsi dan tafsiran ketika menyusun laporan Bab 2 bulan depan", "Menulis kejadian beserta jam dan jumlahnya selama pengamatan, lalu merapikannya pada hari yang sama", "Mencatat kesan umum di kolom tafsiran selama pengamatan, lalu mengisi kolom deskripsi sesudah wawancara"]'::JSONB, 2, '[C3] Fix dkk. (2022) menyarankan informasi dicatat saat itu juga, karena pencatatan yang ditunda menurunkan mutu data. Catatan dari ingatan, foto tanpa catatan, atau deskripsi yang diisi belakangan kehilangan jam, jumlah, dan urutan kejadian.', 16),
  (2, 'Seorang mahasiswa mewawancarai petugas layanan sirkulasi sebuah perpustakaan umum. Petugas itu berkata, "Setiap Senin pagi, kotak pengembalian penuh sampai kami kewalahan." Cara mencatat kutipan itu yang paling tepat untuk studi pendahuluan adalah ...', '["Menulis ringkasannya dengan kata-kata sendiri, disertai nama lengkap narasumbernya", "Menuliskan kesimpulan bahwa petugas sirkulasi kurang cakap mengatur pekerjaannya", "Merekam percakapan diam-diam agar petugas berbicara lebih jujur kepada mahasiswa", "Menulis kalimatnya persis seperti diucapkan, disertai peran narasumber tanpa namanya"]'::JSONB, 3, '[C3] Kutipan ditulis persis dan diberi keterangan peran, misalnya "petugas sirkulasi, 5 tahun bekerja", tanpa nama, setelah meminta izin. Ringkasan dengan nama lengkap mengubah kata narasumber dan membuka identitasnya.', 17),
  (2, 'Catatan mahasiswa tentang repositori tugas akhir sebuah politeknik: (1) 60% unggahan bulan lalu ditolak petugas; (2) panduan unggah belum diperbarui sejak format sampul berubah; (3) petugas verifikasi hanya satu orang; (4) halaman unggah sering gagal memuat. Catatan mana yang merupakan gejala masalah, bukan penyebabnya?', '["Catatan 2, karena panduan yang usang membuat mahasiswa salah mengunggah", "Catatan 3, karena jumlah petugas menentukan kecepatan verifikasi unggahan", "Catatan 1, karena menggambarkan akibat yang terlihat dan dapat dihitung", "Catatan 4, karena halaman yang gagal memuat dialami banyak pengguna"]'::JSONB, 2, '[C4] Penolakan 60% unggahan adalah akibat yang tampak, sedangkan panduan usang, petugas tunggal, dan halaman yang gagal memuat adalah dugaan penyebabnya. Halaman yang gagal memuat memang dialami pengguna, tetapi tetap menjelaskan mengapa unggahan bermasalah, jadi termasuk penyebab.', 18),
  (2, 'Seorang mahasiswa mengklaim bahwa langganan jurnal elektronik di perpustakaan kampusnya jarang dimanfaatkan. Ia mengumpulkan beberapa bahan. Bahan mana yang paling kuat mendukung klaim itu?', '["Statistik akses langganan per bulan dari penyedia, dibandingkan jumlah anggota aktif", "Pernyataan seorang teman sekelas yang belum pernah membuka jurnal elektronik kampus", "Berita nasional tentang rendahnya minat baca mahasiswa di Indonesia secara umum", "Pengalaman mahasiswa itu sendiri yang lebih sering mencari artikel lewat mesin pencari"]'::JSONB, 0, '[C4] Statistik akses dari lokasi yang sama dan dapat dibandingkan dengan jumlah anggota adalah bukti terukur. Berita nasional terdengar kuat, tetapi tidak menggambarkan perpustakaan yang diteliti.', 19),
  (2, 'Dua mahasiswa menyiapkan proposal. Mahasiswa pertama menetapkan topik "aplikasi perpustakaan berbasis web" karena sedang diminati, lalu mencari masalah yang cocok. Mahasiswa kedua mengamati layanan, mewawancarai petugas, menemukan masalah, baru menetapkan topik. Analisis yang paling tepat tentang perbedaan keduanya adalah ...', '["Topik mahasiswa pertama lebih kuat karena mengikuti tren teknologi yang sedang diminati", "Keduanya sama kuat karena pada akhirnya sama-sama menghasilkan produk untuk layanan perpustakaan", "Topik mahasiswa kedua lebih lemah karena waktunya habis untuk observasi dan wawancara", "Topik mahasiswa kedua lebih kuat karena lahir dari masalah yang buktinya sudah terkumpul"]'::JSONB, 3, '[C4] Topik yang baik lahir dari pengamatan kondisi nyata, sehingga bukti untuk latar belakang sudah tersedia. Topik yang dipilih karena tren rawan tidak didukung masalah nyata, walau produknya tampak menarik.', 20),
  (3, 'Dalam proposal pengembangan aplikasi pencatatan pengembalian buku untuk perpustakaan jurusan, seorang mahasiswa menulis: "Petugas sirkulasi dapat mencatat pengembalian buku tanpa menulis ulang di buku besar." Kalimat tersebut paling tepat ditempatkan sebagai ...', '["Manfaat praktis, karena menyebut pihak penerima dan perubahan yang ia alami bila produk berhasil", "Tujuan proyek, karena menyebut apa yang akan dihasilkan mahasiswa pada akhir semester berjalan", "Rumusan masalah, karena menggambarkan kesulitan petugas yang hendak dijawab oleh proyek pengembangan tersebut", "Definisi operasional, karena menjelaskan cara kemudahan pencatatan akan diukur selama uji coba"]'::JSONB, 0, '[C2] Tujuan menyebut apa yang dihasilkan proyek, sedangkan manfaat menyebut apa yang berubah bagi pihak tertentu. Kalimat itu tidak menyebut produk yang dihasilkan, jadi belum berbentuk tujuan.', 21),
  (3, 'Dua mahasiswa berdebat ketika menyusun Bab 1 proposal layanan katalog daring untuk perpustakaan kampus. Yang satu menganggap ruang lingkup dan spesifikasi produk adalah bagian yang sama. Penjelasan yang tepat tentang perbedaan keduanya adalah ...', '["Ruang lingkup memuat alasan memilih produk, sedangkan spesifikasi memuat data masalah dari studi pendahuluan", "Ruang lingkup ditulis sesudah uji coba, sedangkan spesifikasi ditulis sebelum produk mulai dikembangkan", "Ruang lingkup membatasi apa yang dikerjakan proyek, sedangkan spesifikasi menguraikan wujud produknya", "Ruang lingkup berisi daftar fitur produk, sedangkan spesifikasi berisi daftar ahli yang akan memvalidasi"]'::JSONB, 2, '[C2] Bab ini menyebut ruang lingkup membatasi apa yang dikerjakan proyek, sedangkan spesifikasi menguraikan produknya. Kelemahan yang baru diketahui sesudah uji coba dilaporkan di laporan akhir, bukan ditulis sebagai ruang lingkup.', 22),
  (3, 'Seorang mahasiswa sudah menulis judul proposal pada minggu pertama kuliah. Dosen menyarankan agar judul itu ditulis ulang paling akhir. Alasan saran itu yang paling tepat adalah ...', '["Judul yang ditulis belakangan cenderung lebih pendek sehingga lebih mudah diingat oleh penguji proposal", "Judul meringkas rumusan masalah, tujuan, dan spesifikasi produk, sehingga baru tepat setelah ketiganya tetap", "Judul perlu menunggu hasil uji coba produk agar dapat memuat angka keberhasilan proyek mahasiswa", "Judul yang ditulis pada minggu pertama biasanya belum memakai kata Pengembangan di awal kalimatnya"]'::JSONB, 1, '[C2] Judul meringkas rumusan masalah, tujuan, dan spesifikasi produk, jadi judul ditulis ulang setelah ketiganya tidak berubah lagi. Panjang judul tidak dikejar, dan proposal ditulis sebelum uji coba sehingga belum ada angka hasil.', 23),
  (3, 'Tujuan sebuah proposal berbunyi: "Menghasilkan aplikasi pemesanan meja baca yang meningkatkan kenyamanan pemustaka di Perpustakaan Pusat Kampus Rekaan." Istilah dalam tujuan itu yang paling perlu diberi definisi operasional adalah ...', '["\"Aplikasi\", karena pembaca perlu tahu bahasa pemrograman yang dipakai untuk membangunnya", "\"Meja baca\", karena jumlah meja di perpustakaan pusat dapat berubah dari satu tahun ke tahun berikutnya", "\"Perpustakaan pusat\", karena kampus itu mungkin memiliki lebih dari satu gedung layanan", "\"Kenyamanan pemustaka\", karena istilah itu dapat ditafsirkan berbeda dan perlu cara ukur"]'::JSONB, 3, '[C3] Definisi operasional ditulis untuk istilah kunci yang dapat ditafsirkan berbeda dan nantinya diukur dengan instrumen. Lokasi gedung cukup dijelaskan di ruang lingkup, bukan dengan definisi operasional.', 24),
  (3, 'Mahasiswa mengisi tabel ruang lingkup dengan empat aspek: fitur produk, pengguna, lokasi dan waktu, serta tahap pengembangan. Salah satu butirnya: "Produk diuji di perpustakaan fakultas tempat PKL selama satu semester, tidak di perpustakaan pusat." Butir tersebut tepat dimasukkan ke aspek ...', '["Fitur produk, karena menentukan bagian layanan perpustakaan yang akan dibuatkan fiturnya", "Pengguna, karena menentukan kelompok pemustaka yang akan dilibatkan selama proses uji coba", "Lokasi dan waktu, karena menyebut tempat dan rentang waktu proyek beserta tempat yang dikeluarkan", "Tahap pengembangan, karena menyebut sampai tahap mana produk diuji sebelum diterapkan penuh di perpustakaan"]'::JSONB, 2, '[C3] Butir itu menyebut tempat dan rentang waktu, termasuk tempat yang dikeluarkan, jadi masuk aspek lokasi dan waktu. Tahap pengembangan membahas sampai tahap model mana proyek dijalani, bukan di mana proyek dijalankan.', 25),
  (3, 'Mahasiswa sudah menemukan tiga penelitian tentang katalog skripsi daring dan ingin menyatakan celah proyeknya di latar belakang proposal. Cara menuliskan celah yang paling sesuai kaidah adalah ...', '["Satu atau dua kalimat di paragraf terakhir dengan rujukan penelitian terdekat; rincian perbandingan ditulis di Penelitian yang Relevan", "Tabel persamaan dan perbedaan ketiga penelitian di paragraf terakhir, supaya penguji langsung melihat posisi proyek sejak awal", "Satu atau dua kalimat di paragraf pertama, sebelum konteks dan data masalah, supaya pembaca tahu kebaruan proyek lebih dulu", "Satu atau dua kalimat di paragraf terakhir tanpa menyebut penelitian lain, supaya perhatian penguji tetap pada proyek sendiri"]'::JSONB, 0, '[C3] Pernyataan celah cukup satu atau dua kalimat di paragraf terakhir latar belakang, disertai satu atau dua rujukan penelitian terdekat sebagai pembanding. Rincian persamaan dan perbedaan dengan tiap penelitian ditulis di subbab Penelitian yang Relevan (Bab 4).', 26),
  (3, 'Draf judul proposal: "Pengembangan SIBEPUS untuk Layanan Bebas Pustaka Calon Wisudawan di Perpustakaan Politeknik X". SIBEPUS adalah nama aplikasi yang hanya dikenal petugas di tempat PKL. Perbaikan yang paling tepat adalah ...', '["Menambahkan kepanjangan SIBEPUS di daftar istilah, sedangkan judul tetap memakai singkatan itu", "Menambahkan nama model pengembangan di judul supaya pembaca tahu tahapan proyek mahasiswa", "Memendekkan judul menjadi \"Pengembangan SIBEPUS\" agar lebih mudah diingat oleh penguji", "Mengganti SIBEPUS dengan jenis produknya, misalnya aplikasi pengajuan surat bebas pustaka"]'::JSONB, 3, '[C3] Singkatan yang hanya dikenal di tempat PKL dihindari di judul, karena pembaca sampul perlu langsung tahu apa yang dibuat. Istilah produk yang jelas juga membantu tulisan ditemukan lewat mesin pencari (Pottier dkk., 2024).', 27),
  (3, 'Latar belakang sebuah proposal terdiri atas empat paragraf: sejarah perpustakaan di Indonesia, peran perpustakaan dalam pendidikan, perkembangan teknologi informasi, dan kebijakan literasi nasional. Masalah di perpustakaan kampus tempat PKL baru disebut pada kalimat terakhir, tanpa data. Kelemahan utama latar belakang tersebut adalah ...', '["Rujukan teorinya kurang banyak, sehingga keempat paragraf perlu ditambah kutipan dari para ahli", "Konteksnya terlalu panjang, sehingga masalah inti dan data pendukungnya hampir tidak dibahas", "Urutannya terbalik, karena kebijakan literasi nasional seharusnya ditulis pada paragraf pertama", "Jumlah paragrafnya berlebih, sehingga dua paragraf perlu dihapus tanpa mengubah isi lainnya"]'::JSONB, 1, '[C4] Bab ini menyebut dua kesalahan umum: langsung menulis masalah tanpa konteks, atau menulis konteks terlalu panjang tanpa sampai ke masalah inti. Mengurangi paragraf saja tidak menolong bila masalah dan datanya tetap tidak muncul.', 28),
  (3, 'Judul proposal: "Pengembangan Kios Informasi Layanan untuk Perpustakaan Daerah Rekaan". Rumusan masalahnya menyebut "aplikasi web layanan", tujuannya menyebut "sistem informasi layanan", dan spesifikasi produknya menyebut "kios informasi" berupa layar sentuh di lobi. Masalah yang paling mendasar pada proposal tersebut adalah ...', '["Judulnya belum memuat masalah yang hendak dijawab, sehingga perlu ditambah kata mempercepat", "Spesifikasinya terlalu rinci, sehingga bentuk layar sentuh sebaiknya dipindah ke bagian manfaat", "Istilah produk berbeda di tiap bagian, sehingga pembaca tidak yakin produk apa yang dikembangkan", "Tujuannya terlalu teknis, sehingga istilah sistem informasi perlu diganti dengan kata layanan"]'::JSONB, 2, '[C4] Istilah produk di judul harus sama dengan yang dipakai di rumusan masalah dan bagian lain. Menambah kata "mempercepat" justru membawa janji pengukuran waktu yang belum tentu dirancang.', 29),
  (3, 'Perpustakaan Politeknik Rekaan sudah memakai formulir daring perpanjangan pinjaman buatan unit TI sejak bulan lalu. Fiturnya sesuai alur kerja petugas, tetapi formulir itu belum pernah dinilai oleh ahli maupun pemustaka. Mahasiswa ingin mengembangkan dan menguji versi perbaikannya. Celah yang paling dapat dipertanggungjawabkan adalah ...', '["Formulir serupa sudah ada di tempat itu, tetapi kelayakannya belum dinilai oleh ahli dan pengguna setempat", "Formulir serupa sudah ada, tetapi tidak cocok dengan alur kerja petugas sehingga perlu dirancang ulang dari awal", "Formulir serupa belum tersedia di perpustakaan perguruan tinggi vokasi, sehingga proyek ini mengisi kekosongan itu", "Formulir serupa sudah ada, tetapi teknologinya sudah lama sehingga perlu diganti dengan platform yang lebih baru"]'::JSONB, 0, '[C4] Bab ini menyebut dua celah yang mudah dipertanggungjawabkan: produk serupa tidak cocok dengan pengguna atau tempat, atau produk serupa belum dinilai kelayakannya oleh ahli dan pengguna di tempat itu. Keadaan di soal cocok dengan celah kedua; fiturnya sudah sesuai alur sehingga celah pertama tidak berlaku, dan formulirnya sudah ada sehingga klaim kekosongan keliru.', 30),
  (4, 'Seorang mahasiswa PKL di perpustakaan kampus rekaan akan mengembangkan aplikasi peminjaman e-book. Ia menganggap kajian pustaka di proposalnya cukup berisi kutipan pendapat para ahli. Pernyataan yang paling tepat menggambarkan fungsi kajian pustaka dalam proposal pengembangan adalah ...', '["Memperlihatkan banyaknya sumber yang sudah dibaca agar proposal tampak meyakinkan di mata dosen penguji dan pembimbing proyek", "Menunjukkan bahwa produk bertumpu pada pengetahuan yang sudah teruji dan memperlihatkan posisi proyek di antara penelitian lain", "Memuat pendapat para ahli secara lengkap agar pembaca proposal tidak perlu lagi membuka sumber aslinya sendiri", "Menggantikan uraian metode karena langkah pengembangan produk biasanya sudah dijelaskan oleh penelitian lain"]'::JSONB, 1, '[C2] Kajian pustaka adalah landasan berpikir yang menunjukkan proyek dibangun di atas pengetahuan teruji, bukan opini pribadi. Banyaknya sumber tidak menggantikan fungsi itu bila sumbernya tidak diolah menjadi argumen.', 31),
  (4, 'Mahasiswa membaca laporan penelitian 12 halaman tentang layanan referensi daring di perpustakaan umum. Di proposalnya ia menuliskan seluruh hasil penelitian itu dalam dua kalimat dengan kata-katanya sendiri, lalu mencantumkan penulis dan tahun. Cara mengolah gagasan sumber yang ia pakai adalah ...', '["Parafrase, karena gagasan sumber ditulis ulang dengan kalimat mahasiswa sendiri", "Kutipan langsung, karena penulis dan tahun sumber tetap dicantumkan", "Sintesis, karena hasil penelitian itu diolah menjadi argumen proyek", "Ringkasan, karena isi sumber yang panjang dipadatkan menjadi dua kalimat"]'::JSONB, 3, '[C2] Ringkasan memadatkan isi yang panjang, misalnya seluruh hasil penelitian, menjadi satu atau dua kalimat. Parafrase juga memakai kalimat sendiri, tetapi menuliskan ulang satu gagasan, bukan seluruh isi sumber.', 32),
  (4, 'Mahasiswa sudah menggambar kerangka berpikir empat kotak berpanah untuk aplikasi pemesanan ruang diskusi perpustakaan. Dosen meminta bagan itu disertai satu paragraf penjelasan. Alasan permintaan itu yang paling tepat adalah ...', '["Tanpa uraian, pembaca harus menebak hubungan antarkotak dan alasan panah yang menghubungkannya", "Paragraf itu menggantikan subbab tujuan, sehingga proposal menjadi lebih ringkas dan tidak berulang", "Paragraf itu menampung rujukan teori, karena bagan tidak dapat memuat nama penulis dan tahun terbit", "Paragraf itu membuat panah dapat dibaca dua arah, dari masalah ke hasil maupun dari hasil ke masalah"]'::JSONB, 0, '[C2] Kerangka berpikir harus disertai satu paragraf penjelasan, karena bagan tanpa uraian memaksa pembaca menebak hubungan antarkotaknya. Isi kotak hasil tetap diambil dari tujuan, dan alur panahnya dari kiri ke kanan.', 33),
  (4, 'Mahasiswa menyusun peta mind map kajian pustaka untuk aplikasi pengingat jatuh tempo di perpustakaan kampus. Simpul lain sudah terisi, tetapi simpul "praktik baik di industri/lapangan" masih kosong. Bahan yang paling tepat untuk simpul itu adalah ...', '["Teori pembentukan kebiasaan yang menjelaskan mengapa pengingat dapat mengubah perilaku pemustaka", "Artikel jurnal yang menguji pengaruh pengingat terhadap keterlambatan dengan kelompok pembanding dan uji statistik", "Laporan tahunan dan SOP layanan pengingat jatuh tempo dari perpustakaan kota yang sudah menjalankannya", "Peraturan perpustakaan kampus tentang lama peminjaman dan besaran denda keterlambatan buku"]'::JSONB, 2, '[C3] Peta mind map kajian pustaka memuat teori dasar, model pengembangan, studi empiris, data atau regulasi, praktik baik di industri atau lapangan, dan kesenjangan penelitian. Bahan praktik baik berupa dokumen kerja lembaga yang sudah menjalankan layanan serupa, seperti laporan dan SOP. Artikel jurnal dengan uji statistik masuk studi empiris, teori masuk simpul teori, dan peraturan masuk data atau regulasi.', 34),
  (4, 'Mahasiswa ingin membuka latar belakang proposalnya dengan ilustrasi kasus terkini tentang perpustakaan sekolah yang beralih ke katalog daring. Ilustrasi itu tidak dipakai sebagai landasan teori. Sumber yang paling sesuai untuk keperluan tersebut adalah ...', '["Artikel jurnal bereputasi tentang teori temu kembali informasi", "Buku teks manajemen perpustakaan dari penerbit akademik resmi", "Artikel berita daring dari media dengan redaksi yang jelas", "Tulisan blog pribadi yang menceritakan pengalaman memakai katalog"]'::JSONB, 2, '[C3] Artikel berita daring berkredibilitas sedang dan cocok untuk ilustrasi kasus terkini, bukan landasan teori. Jurnal dan buku teks lebih tepat untuk teori dan definisi, sedangkan blog pribadi tanpa kejelasan penulis sebaiknya dihindari.', 35),
  (4, 'Mahasiswa akan memparafrase satu paragraf dari artikel tentang layanan perpustakaan keliling untuk kajian teorinya. Urutan kerja yang paling tepat ia jalankan adalah ...', '["Baca sampai paham, tutup sumber, tulis dari ingatan, cocokkan lagi dengan sumber, lalu cantumkan penulis dan tahun", "Buka sumber di samping draf, ganti kata satu per satu dengan sinonimnya, lalu cantumkan penulis dan tahun", "Salin kalimat sumber, ubah urutan anak kalimatnya agar berbeda, lalu cantumkan kutipan di bagian akhir paragraf tersebut", "Tulis gagasan dari ingatan tanpa membaca ulang sumbernya, lalu periksa kemiripannya dengan aplikasi pemeriksa"]'::JSONB, 0, '[C3] Menutup sumber saat menulis memaksa mahasiswa memakai struktur dan kata sendiri, dan membuka lagi sumber menjaga makna tetap benar. Mengganti sinonim satu per satu menghasilkan patchwriting walaupun kutipannya dicantumkan.', 36),
  (4, 'Mahasiswa membuat kerangka berpikir empat kotak untuk aplikasi presensi pengunjung perpustakaan kampus. Kotak pertama berisi masalah di lapangan, kotak kedua teori dan penelitian, kotak ketiga produk, dan kotak keempat hasil yang diharapkan. Bagian proposal yang paling tepat menjadi asal isi kotak keempat adalah ...', '["Spesifikasi produk yang akan dibangun oleh mahasiswa", "Identifikasi masalah pada Bab 1 proposal mahasiswa", "Tema-tema kajian teori yang dibahas pada Bab 2", "Tujuan pengembangan yang sudah dirumuskan di proposal"]'::JSONB, 3, '[C3] Kotak keempat diisi dari tujuan, sedangkan kotak pertama dari identifikasi masalah, kotak kedua dari tema kajian teori, dan kotak ketiga dari spesifikasi produk. Spesifikasi produk menjelaskan apa yang dibuat, bukan hasil yang diharapkan.', 37),
  (4, 'Proposal aplikasi peminjaman loker di perpustakaan kampus rekaan memuat lima sumber: tiga buku tentang desain layanan dan sistem informasi, serta dua artikel jurnal tentang sistem peminjaman fasilitas di perpustakaan lain. Bagian yang paling perlu dilengkapi dalam kajian pustaka itu adalah ...', '["Penelitian sejenis, karena dua artikel jurnal belum cukup untuk dibandingkan dengan proyek", "Data atau kebijakan pendukung, misalnya aturan layanan loker dan data jumlah pemakainya", "Teori dasar, karena buku tentang desain layanan biasanya belum memuat temuan riset terbaru", "Kutipan langsung dari pakar, karena kajian pustaka itu belum memuat definisi baku tentang loker"]'::JSONB, 1, '[C4] Kajian pustaka penelitian pengembangan idealnya memuat teori dasar, penelitian sejenis, dan data atau kebijakan pendukung. Buku dan artikel sudah mengisi dua jenis pertama, sehingga yang belum ada adalah data dan kebijakan dari lokasi proyek.', 38),
  (4, 'Mahasiswa akan mengembangkan aplikasi katalog untuk perpustakaan SMP. Ia menemukan dua penelitian (rekaan): penelitian pertama melaporkan aplikasi katalog menaikkan kepuasan pemustaka perpustakaan universitas, dan penelitian kedua melaporkan hasil serupa di perpustakaan umum. Belum ada penelitian serupa di perpustakaan sekolah. Kesimpulan yang paling tepat dari temuan itu adalah ...', '["Ada celah pada pengguna perpustakaan sekolah yang dapat menjadi alasan proyek", "Proyek kurang diperlukan karena manfaat aplikasi katalog sudah terbukti di dua jenis perpustakaan", "Kedua penelitian bertentangan sehingga mahasiswa perlu memilih salah satu sebagai landasan proyek", "Hasil kedua penelitian dapat dipakai sebagai perkiraan hasil proyek di perpustakaan SMP tersebut"]'::JSONB, 0, '[C4] Kedua penelitian sejalan, dan pengguna yang belum diteliti menunjukkan celah populasi yang membenarkan proyek. Hasil di universitas dan perpustakaan umum belum tentu berlaku pada siswa SMP, jadi tidak dapat langsung dipakai sebagai hasil proyek.', 39),
  (4, 'Mahasiswa menemukan dua berkas berisi laporan evaluasi layanan sirkulasi yang sama. Berkas pertama ada di situs pribadi, tanpa nama lembaga penerbit dan tanpa tahun. Berkas kedua ada di laman resmi perpustakaan kampus, lengkap dengan nama lembaga, tahun, dan nomor dokumen. Analisis yang paling tepat tentang kedua berkas itu sebagai rujukan adalah ...', '["Kedua berkas setara sebagai rujukan karena isinya sama, sehingga mahasiswa dapat memilih yang paling mudah diunduh", "Berkas di situs pribadi lebih layak dirujuk karena dapat diakses tanpa izin sehingga pembaca mudah memeriksanya", "Berkas di laman resmi lebih layak dirujuk karena penerbit dan tahunnya jelas sehingga dapat ditelusuri", "Kedua berkas kurang layak dirujuk karena laporan lembaga tidak terbit di jurnal yang terindeks Scopus atau Sinta"]'::JSONB, 2, '[C4] Rujukan perlu dapat ditelusuri pembaca, dan laporan resmi lembaga berkredibilitas tinggi untuk data. Isi yang sama belum cukup, karena tanpa penerbit dan tahun entri rujukannya tidak dapat disusun dan diperiksa.', 40),
  (5, 'Dua mahasiswa PKL di perpustakaan kampus menyusun rencana tugas akhir. Rina mengukur kepuasan pemustaka terhadap layanan sirkulasi dengan angket. Bayu membuat panduan digital layanan pinjam antarperpustakaan, meminta ahli menilainya, lalu mengujinya kepada pemustaka. Mengapa rencana Bayu termasuk penelitian pengembangan?', '["Luarannya berupa produk yang dibuat lalu divalidasi dan diuji coba kepada pengguna", "Datanya dikumpulkan dari pemustaka, bukan dari petugas perpustakaan", "Rencananya memakai angket dan wawancara sekaligus dalam satu penelitian", "Topiknya tentang layanan digital yang lebih baru dan lebih jarang diteliti daripada layanan sirkulasi"]'::JSONB, 0, '[C2] Penelitian pengembangan berawal dari masalah dan berakhir pada produk yang sudah divalidasi dan diuji. Sumber data atau jenis instrumen tidak menentukan jenis penelitian.', 41),
  (5, 'Pada gambar model ADDIE, tahap Evaluate diletakkan di tengah dan panahnya mengarah ke Analyze, Design, Develop, dan Implement. Apa makna susunan gambar itu bagi tim yang memakai ADDIE?', '["Evaluasi baru dikerjakan sesudah produk selesai diterapkan kepada pengguna", "Setiap tahap dinilai lebih dulu sebelum tim melanjutkan ke tahap berikutnya", "Tahap evaluasi dapat dilewati bila tim kekurangan waktu di akhir semester", "Keempat tahap lain dikerjakan bersamaan karena semuanya mengarah ke evaluasi"]'::JSONB, 1, '[C2] Evaluasi dalam ADDIE dipakai untuk menilai setiap tahap, bukan hanya di akhir. Itu sebabnya Evaluate digambar di tengah dengan panah ke tahap lain.', 42),
  (5, 'Tim mahasiswa merancang aplikasi peminjaman loker di perpustakaan kampus. Sebelum menulis kode, mereka membuat tiga tampilan utama di Figma. Apa fungsi tiga tampilan itu pada tahap ini?', '["Menjadi produk jadi yang langsung dipasang di perpustakaan", "Menggantikan flowchart sehingga alur tidak perlu digambar lagi", "Menjadi tiruan produk yang cukup untuk dicoba dan dikomentari validator", "Menjadi bukti bahwa aplikasi sudah lolos uji kegunaan dengan angket SUS dari pemustaka"]'::JSONB, 2, '[C2] Prototipe awal adalah tiruan produk yang cukup untuk dicoba dan dikomentari, dan prototipe inilah yang ditunjukkan kepada validator. Prototipe dibuat dari flowchart, bukan menggantikannya.', 43),
  (5, 'Mahasiswa menggambar flowchart peminjaman loker: pemustaka memindai kartu anggota, lalu sistem memeriksa "Masih ada loker kosong?". Bila ya, nomor loker ditampilkan; bila tidak, muncul pesan untuk menunggu. Simbol apa yang tepat untuk langkah pemeriksaan itu?', '["Oval, karena langkah itu menandai titik mulai alur peminjaman", "Persegi panjang, karena langkah itu adalah proses yang dikerjakan sistem", "Panah bercabang, karena langkah itu menunjukkan arah ke dua layar", "Belah ketupat, karena langkah itu adalah keputusan dengan dua jawaban"]'::JSONB, 3, '[C3] Belah ketupat dipakai untuk keputusan, dan langkah ini punya jawaban ya dan tidak. Persegi panjang dipakai untuk proses tanpa percabangan.', 44),
  (5, 'Sebuah tim ingin membuat permainan edukasi tur virtual perpustakaan untuk mahasiswa baru, lengkap dengan misi mencari koleksi dan skor. Bila mengikuti pengelompokan model pada bab ini, model mana yang paling dekat dengan jenis produk tersebut?', '["GDLC, karena tahapnya disusun khusus untuk pengembangan permainan", "Waterfall, karena tahapnya berurutan dan mudah diikuti tim pemula", "Borg dan Gall, karena produknya dipakai mahasiswa sebagai bahan belajar", "RAD, karena permainan perlu selesai cepat sebelum masa orientasi"]'::JSONB, 0, '[C3] GDLC disusun untuk permainan, dengan uji beta oleh pihak di luar tim. Borg dan Gall memang dekat dengan produk pendidikan, tetapi bab ini menempatkan permainan pada kelompok GDLC.', 45),
  (5, 'Seorang pemustaka mengisi angket SUS sesudah mencoba aplikasi pemesanan loker. Ia menjawab 4 pada kelima butir bernomor ganjil dan 1 pada kelima butir bernomor genap. Berapa skor SUS pemustaka itu?', '["75,0", "87,5", "62,5", "50,0"]'::JSONB, 1, '[C3] Butir ganjil: 4 - 1 = 3, lima butir menjadi 15. Butir genap: 5 - 1 = 4, lima butir menjadi 20. Jumlahnya 35, dikali 2,5 sama dengan 87,5.', 46),
  (5, 'Ahli materi menulis masukan: "Jam layanan referensi pada halaman 4 panduan masih memakai jadwal semester lalu." Tim mencatatnya di tabel jejak revisi berkolom sumber, isi masukan, keputusan, dan bukti perubahan. Isian mana yang paling tepat untuk kolom keputusan dan bukti?', '["Ditunda sampai putaran berikutnya; bukti berupa catatan rapat tim", "Tidak dipakai karena jadwal bisa berubah; bukti tidak diperlukan", "Diterima karena salah isi; bukti berupa halaman 4 sebelum dan sesudah revisi", "Diterima tanpa alasan; bukti berupa skor validasi putaran kedua"]'::JSONB, 2, '[C3] Kesalahan isi didahulukan, keputusan ditulis beserta alasannya, dan bukti perubahan berupa nomor halaman atau tangkapan layar sebelum dan sesudah revisi.', 47),
  (5, 'Sesudah validasi putaran pertama aplikasi reservasi ruang diskusi perpustakaan, tim menerima tiga masukan: (a) ahli media meminta warna tombol dibuat lebih kontras; (b) ahli materi mencatat aturan durasi peminjaman ruang di halaman bantuan keliru; (c) pengguna melaporkan tombol Simpan Reservasi tidak menyimpan apa pun. Urutan pengerjaan revisi yang paling tepat adalah ...', '["(a) dan (c) lebih dulu karena keduanya dirasakan langsung oleh pemakai, baru kemudian (b) di halaman bantuan", "(c) lebih dulu karena berasal dari pengguna, baru kemudian (a) dan (b) yang berasal dari ahli media dan ahli materi", "(a) lebih dulu karena paling cepat dikerjakan, baru kemudian (b) dan (c) yang butuh waktu lebih lama", "(b) dan (c) lebih dulu karena menyangkut isi yang salah dan fungsi yang tidak jalan, baru kemudian (a)"]'::JSONB, 3, '[C4] Masukan tentang kesalahan isi dan fungsi yang tidak berjalan didahulukan, baru kemudian soal tampilan. Asal masukan (pengguna atau ahli) dan cepatnya pengerjaan tidak menentukan urutan.', 48),
  (5, 'Tiga tim akan memvalidasi produknya. Tim A membuat aplikasi pemesanan loker dengan sedikit teks. Tim B membuat panduan tertulis prosedur pinjam antarperpustakaan sepanjang dua puluh halaman. Tim C membuat video profil perpustakaan berdurasi tiga menit. Tim mana yang paling perlu menambah ahli bahasa?', '["Tim A, karena aplikasi dipakai banyak pemustaka setiap hari", "Tim B, karena produknya memuat banyak teks petunjuk bagi pengguna", "Tim C, karena video perlu naskah narasi yang menarik penonton", "Ketiganya setara, karena setiap produk perpustakaan memakai bahasa"]'::JSONB, 1, '[C4] Ahli bahasa diperlukan bila produk memuat banyak teks petunjuk, seperti panduan prosedur yang panjang. Aplikasi dengan sedikit teks cukup dinilai ahli materi dan ahli media.', 49),
  (5, 'Tabel kerja tahap ADDIE sebuah tim untuk modul literasi informasi berisi: Analyze = mengujicobakan modul kepada pemustaka; Design = menyusun kerangka dan contoh halaman; Develop = menulis modul dan meminta penilaian ahli; Implement = memakai modul di kelas literasi. Baris mana yang kegiatannya tidak sesuai dengan tahapnya?', '["Design, karena kerangka modul seharusnya disusun pada tahap Develop", "Develop, karena penilaian ahli seharusnya dilakukan pada tahap Implement", "Analyze, karena tahap itu seharusnya menganalisis kebutuhan dan masalah", "Implement, karena modul seharusnya dipakai sesudah tahap Evaluate"]'::JSONB, 2, '[C4] Analyze berisi analisis kebutuhan dan masalah, sedangkan uji coba kepada pemustaka terjadi sesudah produk dikembangkan. Tiga baris lain sudah cocok dengan tahapnya.', 50),
  (6, 'Saat uji coba mesin peminjaman mandiri di perpustakaan kampus, mahasiswa ingin mencatat langkah mana yang membuat pemustaka berhenti atau meminta bantuan petugas, tepat ketika hal itu terjadi. Instrumen apa yang paling sesuai?', '["Angket kepuasan berskala 1 sampai 5 yang diisi pemustaka sesudah selesai meminjam buku.", "Lembar validasi ahli yang diisi pustakawan senior sebelum mesin dipasang di ruang sirkulasi.", "Lembar observasi berisi daftar langkah yang diisi pengamat selama pemustaka memakai mesin.", "Pedoman wawancara yang dipakai seminggu kemudian untuk menanyakan kesan pemustaka."]'::JSONB, 2, '[C2] Lembar observasi dipakai untuk mencatat perilaku atau kejadian secara sistematis saat produk diujicobakan. Angket sesudah meminjam hanya menangkap kesan akhir, bukan langkah yang membuat pemustaka berhenti.', 51),
  (6, 'Mahasiswa memakai dua instrumen untuk aplikasi peminjaman e-book perpustakaan kampus: lembar validasi ahli media dan angket pengguna. Ia berencana memakai satu kisi-kisi untuk keduanya agar ringkas. Mengapa sebaiknya dibuat satu kisi-kisi untuk tiap instrumen?', '["Aspek yang dinilai ahli belum tentu sama dengan aspek yang dirasakan pengguna saat memakai produk.", "Kisi-kisi gabungan membuat butir untuk ahli dan pengguna bernomor sama, sehingga hasilnya sulit dipisahkan.", "Kisi-kisi gabungan membuat jumlah butir tiap instrumen tidak bisa dibuat sama untuk ahli dan pengguna.", "Kisi-kisi gabungan membuat skala Likert ahli dan pengguna harus sama, padahal skalanya berbeda."]'::JSONB, 0, '[C2] Bila memakai dua instrumen, buat satu kisi-kisi untuk tiap instrumen, karena aspek yang dinilai ahli belum tentu sama dengan yang dirasakan pengguna. Jumlah butir, jumlah bab, dan bentuk butir bukan alasannya.', 52),
  (6, 'Mahasiswa menyusun kisi-kisi pedoman wawancara untuk pustakawan yang mencoba aplikasi inventaris koleksi. Contoh butir mana yang paling tepat diisikan pada kolom contoh butir kisi-kisi itu?', '["\"Seberapa setuju Anda bahwa menu inventaris mudah dipahami (1 sampai 5)?\"", "\"Bagian mana yang membuat Anda ragu saat mencatat koleksi baru?\"", "\"Apakah menu inventaris pada aplikasi ini mudah Anda pahami?\"", "\"Bukankah fitur pindai kode batang akan mempercepat pekerjaan Anda?\""]'::JSONB, 1, '[C2] Untuk pedoman wawancara, kolom contoh butir diisi pertanyaan terbuka. Pertanyaan berskala adalah butir angket, pertanyaan ya atau tidak tidak menggali pengalaman narasumber, dan pertanyaan yang menyodorkan solusi mengarahkan jawaban.', 53),
  (6, 'Dua validator menilai lembar validasi sepuluh butir untuk aplikasi katalog perpustakaan sekolah dengan skor 1 sampai 5. Jumlah skor yang diperoleh dari kedua validator adalah 78. Berapa persentase kelayakannya?', '["39%, karena jumlah skor dibagi dua validator lalu dibandingkan dengan 100.", "156%, karena skor maksimum dihitung dari satu validator saja, yaitu 10 x 5 = 50.", "7,8%, karena jumlah skor dibagi jumlah butir lalu dibagi seratus untuk persentase.", "78%, karena skor maksimumnya 2 x 10 x 5 = 100 dan 78 dibagi 100 dikali 100%."]'::JSONB, 3, '[C3] Persentase kelayakan = jumlah skor yang diperoleh dibagi jumlah skor maksimum dikali 100%. Skor maksimumnya 2 validator x 10 butir x 5 = 100, sehingga hasilnya 78%.', 54),
  (6, 'Rencana analisis wawancara di proposal berbunyi: "Transkrip wawancara enam pustakawan dibaca seluruhnya, tiap bagian yang memuat satu gagasan diberi kode, lalu kode yang mirip dikumpulkan menjadi tema." Unsur yang masih perlu ditambahkan adalah ...', '["Asal kode awal, dan keterangan bahwa tiap tema akan disertai satu atau dua kutipan responden.", "Uji Cronbach''s Alpha atas transkrip untuk membuktikan bahwa kode yang dipakai sudah konsisten.", "Persentase kutipan positif dan negatif, supaya hasil wawancara bisa dibandingkan dengan angket.", "Jumlah kata tiap transkrip, supaya panjang jawaban keenam pustakawan dapat dibuat seimbang."]'::JSONB, 0, '[C3] Rencana analisis tematik menuliskan data apa yang dikode, dari mana kode awal diambil, bagaimana kode dikelompokkan menjadi tema, dan bahwa tiap tema disertai satu atau dua kutipan responden. Alpha dipakai untuk skor angket, dan persentase kutipan tidak menggantikan tema.', 55),
  (6, 'Angket kepraktisan aplikasi pengusulan buku berisi 12 butir skala Likert dan diisi 30 pemustaka. Uji reliabilitas menghasilkan Cronbach''s Alpha 0,76. Kesimpulan yang paling sesuai dengan standar pada modul adalah ...', '["Angket belum reliabel, karena koefisien reliabilitas baru dapat diterima bila mencapai 0,90.", "Angket sudah valid, karena Alpha di atas 0,70 menunjukkan butirnya mengukur hal yang tepat.", "Angket dapat diterima dari sisi reliabilitas, karena 0,76 di atas batas 0,70 untuk proyek terapan.", "Angket perlu diganti pedoman wawancara, karena Alpha dirancang untuk lembar validasi ahli."]'::JSONB, 2, '[C3] Cronbach''s Alpha di atas 0,70 dianggap dapat diterima untuk instrumen penelitian terapan berskala kecil menengah. Reliabilitas menunjukkan konsistensi, belum membuktikan validitas, dan Alpha dipakai untuk angket berskala, bukan pedoman wawancara.', 56),
  (6, 'Bab 1 proposal mengutip 5 sumber, Bab 2 mengutip 8 sumber, dan Bab 3 mengutip 4 sumber. Tiga sumber dikutip di Bab 1 dan juga di Bab 2. Mahasiswa juga membaca 2 artikel tentang perpustakaan digital yang tidak dikutip di naskah. Berapa entri Daftar Pustaka-nya?', '["17 entri, karena sumber yang dikutip di tiga bab dijumlahkan apa adanya.", "14 entri, karena sumber yang kembar dihitung sekali dan artikel yang tidak dikutip tidak dimasukkan.", "16 entri, karena sumber kembar dihitung sekali lalu dua artikel yang dibaca ikut dimasukkan.", "19 entri, karena sumber yang dikutip dan yang dibaca dimasukkan sebagai bahan bacaan."]'::JSONB, 1, '[C3] Rujukan yang kembar dibuang dan hanya sumber yang benar-benar dikutip yang masuk Daftar Pustaka: 5 + 8 + 4 - 3 = 14. Artikel yang dibaca tetapi tidak dikutip tidak dicantumkan.', 57),
  (6, 'Angket uji coba aplikasi inventarisasi koleksi untuk petugas perpustakaan sekolah berisi 40 butir. Butirnya sudah ditelaah ahli dan bahasanya jelas, tetapi petugas rata-rata memerlukan 25 menit untuk mengisinya di sela jam layanan. Kriteria instrumen mana yang paling perlu diperbaiki?', '["Validitas isi, karena butir yang terlalu banyak menandakan butir itu tidak sesuai indikator.", "Kejelasan bahasa, karena waktu pengisian yang lama menunjukkan kalimat butir masih sulit dipahami.", "Reliabilitas, karena petugas yang lelah cenderung memberi jawaban yang berbeda bila diulang.", "Kepraktisan, karena waktu pengisian jauh melebihi batas wajar yang idealnya di bawah 10 menit."]'::JSONB, 3, '[C4] Tabel 6.4 menyebut kepraktisan diperiksa dari waktu pengisian yang wajar, idealnya di bawah 10 menit. Stimulus menyebut butir sudah ditelaah ahli dan bahasanya jelas, sehingga validitas isi dan kejelasan bahasa bukan masalah utamanya.', 58),
  (6, 'Dua validator menilai empat butir lembar validasi aplikasi pengingat jatuh tempo perpustakaan umum dengan skala 1 sampai 5. Validator pertama memberi skor 4, 4, 2, 5. Validator kedua memberi skor 4, 3, 5, 5 untuk butir yang sama. Butir mana yang paling perlu dibahas ulang bersama validator?', '["Butir 3, karena selisih skor kedua validator paling besar sehingga kesepakatannya paling rendah.", "Butir 2, karena jumlah skor kedua validator untuk butir itu termasuk yang paling rendah.", "Butir 4, karena kedua validator memberi skor tertinggi sehingga butir itu kurang dapat membedakan.", "Butir 1, karena kedua validator memberi skor 4 yang menandakan butir itu belum sempurna."]'::JSONB, 0, '[C4] Untuk validator yang terbatas, konsistensi dilihat dari tingkat kesepakatan antarpenilai; butir 3 berselisih 3 poin (2 dan 5). Jumlah skor butir 2 adalah 7, sama dengan butir 3, jadi jumlah skor tidak menunjukkan ketidaksepakatan.', 59),
  (6, 'Mahasiswa menyusun pedoman wawancara terbuka untuk menggali pengalaman pustakawan memakai repositori institusi. Ia berencana membuktikan mutu pedoman itu dengan menghitung Cronbach''s Alpha. Apa kelemahan rencana ini?', '["Cronbach''s Alpha memerlukan responden lebih dari 30 orang, sehingga wawancara dengan sedikit pustakawan belum memadai.", "Pedoman wawancara terbuka lebih tepat dinilai dari kredibilitas dan transferabilitas daripada angka statistik.", "Cronbach''s Alpha untuk wawancara dihitung per pertanyaan, sehingga pedoman perlu diubah ke pertanyaan tertutup dulu.", "Cronbach''s Alpha dipakai untuk validitas isi, sehingga reliabilitas pedoman perlu diuji dengan I-CVI."]'::JSONB, 1, '[C4] Bab ini menyebut penilaian mutu instrumen kualitatif seperti pedoman wawancara lebih mengutamakan kredibilitas dan transferabilitas dibanding angka statistik. Cronbach''s Alpha adalah ukuran reliabilitas skor, bukan ukuran validitas isi.', 60);
