-- migration_v46: bank soal Tes Diagnostik Awal, 60 soal (10 per bab, level C2-C4) untuk mata kuliah "Metode Penelitian dan Pengembangan" (antrean #241, 18 Okt 2026).
-- Permintaan Johan: soal diagnostik ditambah supaya tiap mahasiswa "bisa jadi" mendapat soal berbeda. Aplikasi mengambil 20 dari 60
-- secara acak dan seimbang per bab (3-4 per bab), lalu mengacak urutan soal dan opsi.
-- Soal diagnostik LAMA mata kuliah ini DIHAPUS lalu diganti. Skor diagnostik yang sudah tersimpan tidak hilang; untuk
-- percobaan lama, rincian benar per bab tidak lagi bisa dihitung karena soalnya sudah diganti.
-- Satu transaksi; berhenti tanpa perubahan bila mata kuliah atau topik Bab 1-6 tidak ditemukan tepat.

-- LANGKAH 1 (pratinjau, boleh dijalankan sendiri dulu): soal diagnostik lama mata kuliah ini.
-- select count(*) as soal_diagnostik_lama from quiz_questions q join courses c on c.id = q.course_id
-- where q.kind = 'pre' and c.name = 'Metode Penelitian dan Pengembangan';

BEGIN;

DO $$
DECLARE n INT; k INT;
BEGIN
  SELECT count(*) INTO k FROM courses WHERE name = 'Metode Penelitian dan Pengembangan';
  IF k <> 1 THEN RAISE EXCEPTION 'Mata kuliah "Metode Penelitian dan Pengembangan" ditemukan % kali (harus 1). Tidak ada yang diubah.', k; END IF;
  SELECT count(*), count(DISTINCT m.order_num) INTO n, k FROM modules m JOIN courses c ON c.id = m.course_id
   WHERE c.name = 'Metode Penelitian dan Pengembangan' AND m.order_num BETWEEN 1 AND 6;
  IF n <> 6 OR k <> 6 THEN RAISE EXCEPTION 'Topik order_num 1-6: % baris, % nomor berbeda (harus 6 dan 6). Tidak ada yang diubah.', n, k; END IF;
END $$;

CREATE TEMP TABLE diag_baru (bab INT, question TEXT, options JSONB, answer_idx INT, explanation TEXT, order_num INT) ON COMMIT DROP;

DELETE FROM quiz_questions q USING courses c
 WHERE q.kind = 'pre' AND q.course_id = c.id AND c.name = 'Metode Penelitian dan Pengembangan';

SELECT 'pre', NULL, c.id, m.id, d.question, d.options, d.answer_idx, d.explanation, d.order_num
  FROM diag_baru d
  JOIN courses c ON c.name = 'Metode Penelitian dan Pengembangan'
  JOIN modules m ON m.course_id = c.id AND m.order_num = d.bab
 ORDER BY d.order_num;

DO $$
DECLARE n INT;
BEGIN
  SELECT count(*) INTO n FROM quiz_questions q JOIN courses c ON c.id = q.course_id
   WHERE q.kind = 'pre' AND c.name = 'Metode Penelitian dan Pengembangan';
  IF n <> 60 THEN RAISE EXCEPTION 'Soal diagnostik baru % (harus 60). Semua perubahan dibatalkan.', n; END IF;
END $$;

COMMIT;

